// Builds the "Restaurants v2" tab with the full tiered schema.
//
// Rebuild rule: replace, not merge. A row only exists if a citable authority
// put it there. Every row carries Source + Last Checked so it ages visibly.
//
// CORE fields block publication if empty. ENRICHMENT fields are left blank when
// the research did not establish them - a blank cell is honest, a guessed one
// is not. The fill-rate report at the end is the point: it tells us whether the
// wide schema is realistic before we commit 20 cuisines to it.
//
//   node scripts/write-restaurants-v2.mjs
//
import { writeTab, readTab, ensureTab, getSheets, SHEET_ID } from "./sheets.mjs";
import fs from "node:fs";
import path from "node:path";

const TODAY = "2026-08-17";

// ------------------------------------------------------------- geography ---
// Zone and District are keyed off Neighbourhood, so a row never carries a
// hand-typed zone. Zone is the TfL fare zone; District is the compass split
// London actually uses. They answer different questions and neither derives
// from the other: Shoreditch is Zone 1 but nobody calls it central, Canary
// Wharf is Zone 2 and firmly East.
//
// "Central London" is NOT District = Central. It is Zone starting with 1,
// which correctly keeps Borough Market and the South Bank in - they sit south
// of the river but are squarely inside the visitor core.
const DISTRICTS = ["Central", "North", "East", "South", "West"];

