// Coffee shops. Cuisine is deliberately BLANK: these are filed by venueFormat
// and speciality, not by a cooking tradition they do not have. Where a coffee
// shop genuinely cooks to one - Bar Italia is Italian and is filed that way -
// it belongs under that cuisine instead of here.
const cof = { ...base, cuisine: "" };
// Bakeries, patisseries and gelaterias. Cuisine blank for the same reason as
