  // ------------------------------- Wetherspoon pass, 2026-08-23 -----------
  // WHY A CHAIN GETS INDIVIDUAL ROWS AT ALL.
  // Wetherspoon runs roughly 800 pubs and by the chainType rule above that
  // makes it "ubiquitous" - a fallback mention, never a destination. That rule
  // is right about the BRAND and wrong about four specific buildings, because
  // Wetherspoon's estate strategy is to take on listed buildings nobody else
  // can fill: a 1913 banking hall, a railway hotel ballroom, a Georgian dock
  // office, a 1911 cinema. Those are not interchangeable with a high-street
  // Spoons and a visitor would travel to see them.
  //
  // So each row here is ONE NAMED PUB, not the brand. chainType stays
  // "independent" because that field is sized on how many sites THIS row
