// -------------------------------------------------------------- overrides ---
// The Overrides tab is the one part of the spreadsheet a human owns. This
// script clears and rewrites "Restaurants v2" on every run, so a value typed
// straight into that tab is destroyed on the next build. Overrides survive,
// because they are read back in and re-applied every time.
//
// Precedence, highest first:
//   1. Overrides tab   - a person decided this
//   2. Script rows     - researched and version-controlled
//   3. Enrichment cache- derived from APIs
//
// Applied TWICE on purpose: once before the geography derivation, so that
// overriding Neighbourhood correctly re-derives Zone/District/Central, and
// again at the very end, so that overriding Zone directly still wins over that
// derivation. Applying twice is idempotent and avoids tracking dirty fields.
const OVERRIDE_HEADER = ["Slug", "Column", "Value", "Note", "Added"];
const HEAD_TO_KEY = Object.fromEntries(COLUMNS.map((c) => [c.head.toLowerCase(), c.key]));

async function loadOverrides() {
  const created = await ensureTab("Overrides");
  if (created) {
    const sheets = await getSheets();
    await sheets.spreadsheets.values.update({
      spreadsheetId: SHEET_ID,
      range: "Overrides!A1",
      valueInputOption: "RAW",
      requestBody: {
        values: [
          OVERRIDE_HEADER,
          ["# one edit per row. Column must match a header in Restaurants v2 exactly.",
           "", "", "Use (blank) as the Value to clear a field.", ""],
        ],
      },
    });
    console.log('created "Overrides" tab - edits there survive every rebuild');
    return [];
  }
  return (await readTab("Overrides")).filter((r) => r.Slug && !r.Slug.startsWith("#"));
}

const overrides = await loadOverrides();
const bySlugOverride = {};
const overrideProblems = [];

for (const o of overrides) {
  const key = HEAD_TO_KEY[String(o.Column ?? "").trim().toLowerCase()];
  if (!key) {
    overrideProblems.push(`  ${o.Slug}: column "${o.Column}" is not a Restaurants v2 header`);
    continue;
  }
  if (String(o.Value ?? "").trim() === "") {
    overrideProblems.push(`  ${o.Slug}: "${o.Column}" has an empty Value - use (blank) to clear`);
    continue;
  }
  (bySlugOverride[o.Slug] ??= {})[key] =
    o.Value.trim() === "(blank)" ? "" : o.Value.trim();
}

function applyOverrides(rows) {
  let n = 0;
  for (const r of rows) {
    const o = bySlugOverride[r.slug];
    if (!o) continue;
    for (const [k, v] of Object.entries(o)) { r[k] = v; n++; }
  }
  return n;
}

const knownSlugs = new Set(rows.map((r) => r.slug));
for (const s of Object.keys(bySlugOverride)) {
  if (!knownSlugs.has(s)) overrideProblems.push(`  ${s}: no such slug in Restaurants v2`);
}

const appliedCount = applyOverrides(rows);
if (appliedCount) {
  console.log(`overrides: applied ${appliedCount} value(s) across ${Object.keys(bySlugOverride).length} row(s)`);
}
if (overrideProblems.length) {
  console.log(`\nOVERRIDE PROBLEMS (${overrideProblems.length}) - these were IGNORED:`);
  overrideProblems.forEach((p) => console.log(p));
  console.log("");
}

// ------------------------------------------------ derive zone / district ---
// Done here rather than typed per row: 34 rows share 21 neighbourhoods, so
// hand-typing would mean 34 chances to disagree with itself.
//
// For a MULTI-SITE brand, one Neighbourhood cannot describe the brand. Franco
// Manca listed as "Brixton" derives Zone 2 / South / Central FALSE, when it has
// 35+ sites and plenty are Zone 1 - and Brixton is one of the nine closing. So
// a chain's geography is aggregated from the Branches tab, and a chain with no
// branch rows is marked flagship-only so it can be excluded from area filters
// until someone does the research.
// Only mini-chains get branch rows. A 9+ site chain is marked ubiquitous
// instead: its branches are interchangeable, nobody travels to a specific one,
// and the addresses rot fast - Franco Manca closed 9 of ~35 London sites in a
// single year. Listing them would be a maintenance liability that buys nothing
// editorially. A ubiquitous brand is a fallback mention in an area guide
// ("there is usually one nearby"), never a destination recommendation.
const MULTI = ["mini-chain"];
const branchRows = await readTab("Branches");
const branchesByBrand = {};
for (const b of branchRows) {
  if (b.Branch === "UNKNOWN" || !b.Neighbourhood) continue;
  (branchesByBrand[b.Restaurant] ??= []).push(b);
}

const uniq = (a) => [...new Set(a)].filter(Boolean);
const unknownHoods = new Set();

for (const r of rows) {
  const isMulti = MULTI.includes(r.chainType);
  const branches = branchesByBrand[r.name] ?? [];

  if (isMulti && branches.length) {
    // Aggregate: the brand is central if ANY branch is in the visitor core.
    const geos = branches.map((b) => HOODS[b.Neighbourhood]).filter(Boolean);
    for (const b of branches) if (!HOODS[b.Neighbourhood]) unknownHoods.add(b.Neighbourhood);
    r.locationBasis = "all-branches";
    r.branchCount = String(branches.length);
    r.zone = uniq(geos.map((g) => g.zone)).sort().join(", ");
    r.district = uniq(geos.map((g) => g.district)).sort().join(", ");
    r.central = geos.some((g) => isCentral(g.zone)) ? "TRUE" : "FALSE";
    continue;
  }

  // A 9+ site chain is everywhere by definition. Its listed hood is just the
  // original, so zone/district/central are left blank rather than filled with
  // one arbitrary site - a blank cannot mislead a filter, a wrong value can.
  if (r.chainType === "chain") {
    r.locationBasis = "ubiquitous";
    r.zone = "";
    r.district = "";
    r.central = "";
    continue;
  }

  const geo = HOODS[r.hood];
  if (!geo) {
    if (r.hood) unknownHoods.add(r.hood);
    if (isMulti) r.locationBasis = "flagship-only";
    continue;
  }
  // A mini-chain with no branch research: the location describes ONE site, so
  // it must not be trusted as the brand's geography.
  r.locationBasis = isMulti ? "flagship-only" : "single-site";
  r.zone = geo.zone;
  r.district = geo.district;
  r.central = isCentral(geo.zone) ? "TRUE" : "FALSE";
}

const flagshipOnly = rows.filter(
  (r) => r.status === "open" && r.locationBasis === "flagship-only",
);
if (flagshipOnly.length) {
  console.log(`\nFLAGSHIP-ONLY - multi-site brands with no Branches rows (${flagshipOnly.length}):`);
  console.log("  Zone/District/Central describe ONE site and must not be used");
  console.log("  for area filtering until these are researched.\n");
  for (const r of flagshipOnly) {
    console.log(`  ${r.name.padEnd(30)} ${r.chainType.padEnd(11)} listed as ${r.hood}`);
  }
}
if (unknownHoods.size) {
  console.log(`\nNO GEOGRAPHY for ${unknownHoods.size} neighbourhood(s) - add to HOODS:`);
  for (const h of unknownHoods) console.log(`  ${h}`);
  console.log("");
}

// District is multi-value for an aggregated chain ("East, South, West"), so
// validate each part rather than the joined string.
const badDistrict = rows.filter((r) =>
  String(r.district ?? "").split(",").map((s) => s.trim()).filter(Boolean)
    .some((d) => !DISTRICTS.includes(d)),
);
if (badDistrict.length) {
  console.error(`district must be one of [${DISTRICTS.join(", ")}]:`);
  badDistrict.forEach((r) => console.error(`  ${r.slug}: "${r.district}"`));
  process.exit(1);
}

// ------------------------------------------------- merge enrichment cache ---
// data/enrichment.json is produced by scripts/enrich.mjs. Merging here rather
// than writing to the sheet directly means this script stays the single owner
// of the tab, and the expensive lookups survive every rebuild.
//
// Hand-written values WIN over enriched ones. A researched address or walk time
// carries an editorial judgement the API does not have - Mucci's "20 min from
// Fulham Broadway" is computed, but a note about which bus to take is not.
const ENRICH_PATH = "data/enrichment.json";
const ENRICH_MAP = {
  website: "website", postcode: "postcode", lat: "lat", lng: "lng",
  placeId: "placeId", bookingUrl: "bookingUrl",
  bookingPlatform: "bookingPlatform", closedDays: "closedDays", walkMin: "walkMin",
  address: "address", station: "station", pressKit: "pressKit", rating: "rating", ratingCount: "ratingCount",
};

let enriched = 0;
if (fs.existsSync(ENRICH_PATH)) {
  const cache = JSON.parse(fs.readFileSync(ENRICH_PATH, "utf8"));
  const statusFlags = [];
  const chainBranchFlags = [];
  for (const r of rows) {
    const e = cache[r.slug];
    if (!e) continue;
    for (const [col, key] of Object.entries(ENRICH_MAP)) {
      const v = e[key];
      if (v === undefined || v === "" || v === null) continue;
      if (String(r[col] ?? "").trim() !== "") continue; // hand-written wins
      r[col] = String(v);
      enriched++;
    }
    // Google disagreeing with our Status is a maintenance signal, never an
    // automatic overwrite - a row is only retired by a human.
    //
    // Ubiquitous chains are EXCLUDED. Places resolves a chain to one arbitrary
    // branch, so its status describes that branch and not the brand: Franco
    // Manca matched its Brixton site, which genuinely closed as one of the nine
    // shut in 2026, while 25+ other branches trade on. Flagging that as a brand
    // closure would be wrong in exactly the way this check exists to prevent.
    // A press office sits at GROUP level, so a venue with no press page of its
    // own inherits its group's. Claridge's does not link Maybourne's media
    // centre from its own homepage, but it is still where its images come from.
    // Venue-level always wins; this only fills a blank.
    if (!r.pressKit && r.ownerGroup) {
      const grp = cache[`group:${r.ownerGroup}`];
      if (grp?.pressKit) {
        r.pressKit = grp.pressKit === "contact-only"
          ? `contact-only (via ${r.ownerGroup})`
          : `${grp.pressKit} (group)`;
        enriched++;
      }
    }

    if (e.businessStatus && e.businessStatus !== "OPERATIONAL" && r.status === "open") {
      if (r.chainType === "chain") {
        chainBranchFlags.push(
          `  ${r.slug}: Google matched "${e.placesName}" (${e.businessStatus}) - ONE branch, not the brand`,
        );
      } else {
        statusFlags.push(`  ${r.slug}: Google says ${e.businessStatus}, sheet says open`);
      }
    }
  }
  console.log(`merged ${enriched} enriched value(s) from ${ENRICH_PATH}`);
  if (chainBranchFlags.length) {
    console.log(`
CHAIN BRANCH STATUS (${chainBranchFlags.length}) - informational, NOT a brand closure:`);
    chainBranchFlags.forEach((s) => console.log(s));
  }
  if (statusFlags.length) {
    console.log(`\nSTATUS CONFLICT (${statusFlags.length}) - check before publishing:`);
    statusFlags.forEach((s) => console.log(s));
  }
} else {
  console.log(`no ${ENRICH_PATH} yet - run: node scripts/enrich.mjs`);
}

// ------------------------------------------------------------- evidence ---
// How many independent DOMAINS name this venue, across which tiers, and the
// links to them. Derived by scripts/build-evidence.mjs from data/consensus.
//
// WHY IT IS A DERIVED COLUMN RATHER THAN A NOTE
// The Signals column carried this as prose - "3 sources: Good Food Guide,
// Olive Magazine, A Lady in London" - which cannot be sorted, counted or
// checked, and went stale the moment a fourth source turned up. Recomputed on
// every write, a page can state its own support and still be right a year on.
//
// NEVER type these by hand. A hand-typed source count is a claim; a derived one
// is a measurement.
const EVIDENCE_PATH = "data/evidence.json";
const evNorm = (x) =>
  String(x).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/&/g, " and ").replace(/^(the|a)\s+/, "").replace(/[^a-z0-9]+/g, "");

if (fs.existsSync(EVIDENCE_PATH)) {
  const ev = JSON.parse(fs.readFileSync(EVIDENCE_PATH, "utf8"));
  let evMatched = 0;
  for (const r of rows) {
    const hit = ev[evNorm(r.name)];
    if (!hit) continue;
    r.sourceCount = String(hit.sourceCount);
    r.tierSpread = hit.tierSpread;
    // Three links is enough to show provenance and keeps the cell inside the
    // sheet's limit. The full set stays in data/evidence.json.
    r.sourceUrls = hit.sources.slice(0, 3).map((x) => x.url).join(" | ");
    evMatched++;
  }
  const open = rows.filter((r) => r.status !== "closed");
  const thin = open.filter((r) => Number(r.sourceCount ?? 0) < 2).length;
  console.log(`merged evidence for ${evMatched}/${rows.length} row(s) from ${EVIDENCE_PATH}`);
  console.log(`  ${thin} of ${open.length} open row(s) have fewer than 2 independent sources`);
} else {
  console.log(`no ${EVIDENCE_PATH} yet - run: node scripts/build-evidence.mjs`);
}


// Second pass: enrichment and the geography derivation have both run, so
// re-apply so a human's explicit value wins over anything computed.
applyOverrides(rows);

crossCheckZones(rows);
validate(rows);

// ------------------------------------------------------- slug registry ---
// Slugs become URLs. Once a slug has been published, losing it silently is a
// broken page, so the registry is append-only: it records every slug ever seen
// and is never allowed to shrink.
//
// This is the guard against the failure mode this script invites - it clears
// the whole tab on every run, so an accidental edit that drops a row would
// otherwise vanish without trace.
const REGISTRY_PATH = "data/slugs.json";
const allowRemovals = process.argv.includes("--allow-removals");

const registry = fs.existsSync(REGISTRY_PATH)
  ? JSON.parse(fs.readFileSync(REGISTRY_PATH, "utf8"))
  : {};

const currentSlugs = new Set(rows.map((r) => r.slug));
const known = Object.keys(registry);
const missing = known.filter((s) => !currentSlugs.has(s));

if (missing.length && !allowRemovals) {
  console.error(`\nREFUSING TO WRITE - ${missing.length} known slug(s) would disappear:\n`);
  for (const s of missing) {
    const r = registry[s];
    console.error(`  ${s}`);
    console.error(`     first seen ${r.firstSeen}, last seen ${r.lastSeen}, status "${r.status}"`);
  }
  console.error(`
A slug is a URL. Dropping one breaks a page rather than updating it.

  To RETIRE a place, keep the row and set status: "closed" - the way
  locanda-locatelli is kept. It stays in the data and off the site.

  To genuinely remove these, re-run with --allow-removals and add a
  redirect in vercel.json for any slug that was ever published.
`);
  process.exit(1);
}

if (missing.length) {
  console.log(`\nREMOVING ${missing.length} slug(s) (--allow-removals):`);
  missing.forEach((s) => console.log(`  ${s}  - add a redirect if it was published`));
  missing.forEach((s) => delete registry[s]);
}

let added = 0;
for (const r of rows) {
  const existing = registry[r.slug];
  if (!existing) added++;
  registry[r.slug] = {
    name: r.name,
    firstSeen: existing?.firstSeen ?? TODAY,
    lastSeen: TODAY,
    status: r.status,
  };
}
fs.mkdirSync("data", { recursive: true });
fs.writeFileSync(
  REGISTRY_PATH,
  JSON.stringify(Object.fromEntries(Object.entries(registry).sort()), null, 2) + "\n",
);
if (added) console.log(`registry: ${added} new slug(s), ${Object.keys(registry).length} total`);

// ----------------------------------------------------------------- write ---
const header = COLUMNS.map((c) => c.head);
const values = rows.map((r) => COLUMNS.map((c) => r[c.key] ?? ""));

// Snapshot what is about to be destroyed. One run of undo is enough to recover
// from a bad edit, and it costs one read.
try {
  const prev = await readTab("Restaurants v2");
  if (prev.length) {
    fs.writeFileSync(
      "data/snapshot-restaurants-v2.json",
      JSON.stringify(prev, null, 2) + "\n",
    );
    console.log(`snapshot: ${prev.length} previous row(s) -> data/snapshot-restaurants-v2.json`);
  }
} catch {
  console.log("snapshot: could not read previous tab (first run?)");
}

// --dry-run runs every validation and report below without touching the sheet.
// Added alongside the same flag on write-activities.mjs: rows land in batches
// and there is no reason to rewrite 700 rows to find out a speciality is
// spelled wrong.
const dryRun = process.argv.includes("--dry-run");
const n = dryRun ? values.length : await writeTab("Restaurants v2", header, values);

console.log(
  dryRun
    ? `DRY RUN - ${n} rows x ${COLUMNS.length} columns, nothing written\n`
    : `wrote ${n} rows x ${COLUMNS.length} columns\n`,
);

// ------------------------------------------------------- fill-rate report ---
const pct = (f, t) => `${String(Math.round((f / t) * 100)).padStart(3)}%`;
const core = COLUMNS.filter((c) => c.tier === "core");
const enrich = COLUMNS.filter((c) => c.tier === "enrich");
const filled = (c) => rows.filter((r) => String(r[c.key] ?? "").trim() !== "").length;

// Rows that are EXEMPT from a core field rather than missing it. Coffee shops
// carry no Cuisine on purpose - see the cof const and data/consensus/coffee.json.
// Without this the report shows a gap that can never be closed.
const exempt = (c) =>
  c.key === "cuisine" ? rows.filter((r) => r.venueFormat === "Coffee Shop").length : 0;

// --- area guide integrity -------------------------------------------------
// Rows may only point at a guide that exists. A dangling reference is worse
// than a blank one: blank reads as "not placed yet", dangling reads as placed.
{
  const dir = "src/content/articles";
  const onDisk = new Set(fs.existsSync(dir)
    ? fs.readdirSync(dir).filter((f) => f.endsWith("-area-guide.md")).map((f) => f.replace(/\.md$/, ""))
    : []);
  const dangling = {};
  for (const r of rows) {
    const g = String(r.areaGuide ?? "").trim();
    if (g && onDisk.size && !onDisk.has(g)) dangling[g] = (dangling[g] ?? 0) + 1;
  }
  const bad = Object.entries(dangling);
  if (bad.length) {
    console.log("\nDANGLING AREA GUIDES - rows point at a guide with no file on disk:");
    for (const [g, n] of bad.sort((a, b) => b[1] - a[1])) console.log(`   ${String(n).padStart(3)}  ${g}`);
    console.log("  Either write the guide or blank the field. A dangling reference reads as placed when it is not.");
  }
  const empty = [...onDisk].filter((g) => !rows.some((r) => r.areaGuide === g));
  if (empty.length) console.log(`\nGUIDES WITH ZERO ROWS: ${empty.map((e) => e.replace("-area-guide", "")).join(", ")}`);

  // Destination rows and fallback rows counted apart. Only destinations count
  // toward the six-row target - a guide propped up by standbys is still thin,
  // and showing one number would hide exactly that.
  const perGuide = {};
  for (const r of rows) {
    const g = String(r.areaGuide ?? "").trim();
    if (!g) continue;
    (perGuide[g] ??= { dest: 0, fb: 0 });
    if (String(r.fallback ?? "") === "yes") perGuide[g].fb++; else perGuide[g].dest++;
  }
  const thin = Object.entries(perGuide).filter(([, v]) => v.dest < 6).sort((a, b) => a[1].dest - b[1].dest);
  if (thin.length) {
    console.log(`\nTHIN GUIDES - under six DESTINATION rows (fallbacks shown separately, they do not count):`);
    for (const [g, v] of thin)
      console.log(`   ${String(v.dest).padStart(2)} dest${v.fb ? ` + ${v.fb} fallback` : ""}   ${g.replace("-area-guide", "")}`);
  }
}

// Rows written from an announcement whose prose was never revisited. The
// status flag says open; the sentence still says "announced" or "due to open".
// Barbarella shipped like that onto a live page - written in 2025 from the
// announcement, opened June 2026, still reading as forthcoming in August.
{
  const FUTURE = /\b(announced \d{4}|announced for|due to open|opening (soon|later|next)|opens (soon|later|next)|coming soon|will open|set to open|slated to open|yet to open)\b/i;
  const stale = rows.filter((r) =>
    String(r.status ?? "open") === "open" &&
    [r.whyGo, r.opSummary, r.currentView].some((t) => FUTURE.test(String(t ?? ""))));
  if (stale.length) {
    console.log(`\nPRE-OPENING PROSE - ${stale.length} open row(s) still describe the venue as forthcoming:`);
    for (const r of stale) console.log(`   ${r.name}`);
    console.log("  Check whether it opened and rewrite the sentence. Status being right is not enough.");
  }
}

console.log(`CORE (${core.length} cols) - these block publication if empty:`);
for (const c of core) {
  const f = filled(c);
  const ex = exempt(c);
  const applicable = rows.length - ex;
  const gap = applicable - f;
  const note = gap > 0 ? `   <-- ${gap} missing` : ex ? `   (${ex} exempt: coffee shops carry no cuisine)` : "";
  console.log(`  ${pct(f, applicable)}  ${c.head}${note}`);
}

console.log(`\nENRICHMENT (${enrich.length} cols) - blank is acceptable:`);
const byGroup = {};
for (const c of enrich) (byGroup[c.group] ??= []).push(c);
for (const [g, cols] of Object.entries(byGroup)) {
  const tot = cols.reduce((a, c) => a + filled(c), 0);
  console.log(`  ${pct(tot, cols.length * rows.length)}  ${g.padEnd(15)} (${cols.map((c) => `${c.head} ${filled(c)}`).join(", ")})`);
}

const allCells = COLUMNS.length * rows.length;
const allFilled = COLUMNS.reduce((a, c) => a + filled(c), 0);
console.log(`\nOVERALL FILL: ${allFilled}/${allCells} cells = ${pct(allFilled, allCells)}`);

// --------------------------------------------------- coverage by slice ---
// The whole point of the specialities field: check the page-level slices are
// deep enough to publish before committing more cuisines to this shape.
const open = rows.filter((r) => r.status === "open");
const tally = (fn) => {
  const t = {};
  for (const r of open) for (const v of fn(r)) t[v] = (t[v] ?? 0) + 1;
  return Object.entries(t).sort((a, b) => b[1] - a[1]);
};
const csv = (key) => (r) =>
  String(r[key] ?? "").split(",").map((s) => s.trim()).filter(Boolean);

console.log(`\nCOVERAGE (${open.length} open rows):`);
for (const [label, fn] of [
  ["specialities", csv("specialities")],
  ["price band  ", (r) => [r.priceBand || "(blank)"]],
  ["venue format", (r) => [r.venueFormat || "(blank)"]],
  ["zone        ", (r) => [r.zone || "(blank)"]],
  ["district    ", (r) => [r.district || "(blank)"]],
]) {
  console.log(`  ${label}  ${tally(fn).map(([k, v]) => `${k} ${v}`).join(", ")}`);
}

const noArea = open.filter((r) => !r.areaGuide).length;
console.log(`  area guide    ${open.length - noArea} placed, ${noArea} unplaced`);

// ------------------------------------------------------ deal staleness ---
// Deals are the one field that goes wrong silently: the row still looks
// complete long after the offer is withdrawn. Anything unchecked for 90 days
// is treated as unpublishable until someone re-checks it.
const STALE_DAYS = 90;
const withDeals = rows.filter((r) => String(r.deals ?? "").trim());
if (withDeals.length) {
  const now = new Date(TODAY);
  const age = (d) => Math.round((now - new Date(d)) / 86400000);
  console.log(`\nDEALS (${withDeals.length} rows):`);
  for (const r of withDeals) {
    const days = r.dealChecked ? age(r.dealChecked) : null;
    const flag =
      days === null ? "  NO CHECK DATE - do not publish"
      : days > STALE_DAYS ? `  STALE (${days}d) - re-check before publishing`
      : `  checked ${days}d ago`;
    console.log(`  ${r.name.padEnd(22)} ${String(r.deals).padEnd(14)}${flag}`);
  }
}

// The slice the Central London page would actually draw from.
const central = open.filter((r) => r.central === "TRUE");
console.log(`\nCENTRAL LONDON slice: ${central.length}/${open.length} open rows`);
const cSpec = {};
for (const r of central) for (const s of csv("specialities")(r)) cSpec[s] = (cSpec[s] ?? 0) + 1;
console.log(`  specialities  ${Object.entries(cSpec).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(", ")}`);
console.log(`  price bands   ${tally((r) => central.includes(r) ? [r.priceBand] : []).map(([k, v]) => `${k} ${v}`).join(", ")}`);
